def cmp_semver(a, b):
    def parse(v):
        v = v.split('+', 1)[0]          # drop build metadata entirely
        if '-' in v:
            core, pre = v.split('-', 1)
        else:
            core, pre = v, None
        major, minor, patch = (int(x) for x in core.split('.'))
        return (major, minor, patch, pre)

    ma, mb = parse(a), parse(b)

    # compare major.minor.patch numerically
    for i in range(3):
        if ma[i] != mb[i]:
            return -1 if ma[i] < mb[i] else 1

    pa, pb = ma[3], mb[3]

    # a version WITH a pre-release sorts BEFORE the same without one
    if not pa and pb:
        return 1
    if pa and not pb:
        return -1
    if not pa:
        return 0

    for x, y in zip(pa.split('.'), pb.split('.')):
        xn, yn = x.isdigit(), y.isdigit()
        if xn or yn:
            if xn and yn:                       # both numeric -> numeric compare
                nx, ny = int(x), int(y)
                if nx != ny:
                    return -1 if nx < ny else 1
            elif xn:                            # numeric sorts before alphanumeric
                return -1
            else:
                return 1
        else:                                    # both alphanumeric -> ASCII order
            if x != y:
                return -1 if x < y else 1

    # all preceding identifiers equal -> longer pre-release list wins
    la, lb = len(pa.split('.')), len(pb.split('.'))
    if la != lb:
        return -1 if la < lb else 1
    return 0
