def parse_range(header, size):
    if not isinstance(header, str) or size < 0:
        return None

    header = header.strip()
    if not header.lower().startswith("bytes="):
        return None

    spec = header[len("bytes="):]
    results = []

    for part in spec.split(","):
        part = part.strip()
        if "-" not in part:
            return None

        dash = part.index("-")
        start_s = part[:dash].strip()
        end_s = part[dash + 1:].strip()

        if start_s == "":
            # Suffix range: -N
            if end_s == "":
                return None
            try:
                n = int(end_s)
            except ValueError:
                return None
            if n < 0:
                return None
            if n >= size:
                start, end = 0, size - 1
            else:
                start, end = size - n, size - 1
        else:
            try:
                start = int(start_s)
            except ValueError:
                return None
            if start < 0:
                return None
            if end_s == "":
                end = size - 1
            else:
                try:
                    end = int(end_s)
                except ValueError:
                    return None
                if end < 0:
                    return None
                if end > size - 1:
                    end = size - 1

        # Drop unsatisfiable ranges (start beyond resource, or empty range).
        if start >= size or end < start:
            continue

        results.append((start, end))

    return results or None
```

