def unified_diff(a, b, context=3):
    M = len(a)
    N = len(b)

    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (N + 1) for _ in range(M + 1)]
    for i in range(M - 1, -1, -1):
        ai = a[i]
        row = dp[i]
        below = dp[i + 1]
        for j in range(N - 1, -1, -1):
            if ai == b[j]:
                row[j] = below[j + 1] + 1
            else:
                x = below[j]
                y = row[j + 1]
                row[j] = x if x >= y else y

    # Backtrack into per-line operations.
    ops = []
    i = j = 0
    while i < M and j < N:
        if a[i] == b[j]:
            ops.append(('equal', i, j))
            i += 1
            j += 1
        elif dp[i + 1][j] >= dp[i][j + 1]:
            ops.append(('delete', i, j))
            i += 1
        else:
            ops.append(('insert', i, j))
            j += 1
    while i < M:
        ops.append(('delete', i, j))
        i += 1
    while j < N:
        ops.append(('insert', i, j))
        j += 1

    L = len(ops)
    if L == 0:
        return []

    # Find maximal runs of changed (non-equal) operations.
    changes = []
    k = 0
    while k < L:
        if ops[k][0] != 'equal':
            start = k
            while k < L and ops[k][0] != 'equal':
                k += 1
            changes.append((start, k))
        else:
            k += 1

    if not changes:
        return []

    # Expand each change by up to `context` equal lines on either side.
    hunks = []
    for cs, ce in changes:
        lo = cs
        left = 0
        while lo > 0 and left < context and ops[lo - 1][0] == 'equal':
            lo -= 1
            left += 1
        hi = ce
        right = 0
        while hi < L and right < context and ops[hi][0] == 'equal':
            hi += 1
            right += 1
        hunks.append([lo, hi])

    # Merge overlapping or touching hunks.
    merged = []
    for h in hunks:
        if merged and h[0] <= merged[-1][1]:
            if h[1] > merged[-1][1]:
                merged[-1][1] = h[1]
        else:
            merged.append([h[0], h[1]])

    # Prefix counts of a-lines and b-lines consumed up to each op index.
    a_before = [0] * (L + 1)
    b_before = [0] * (L + 1)
    for idx in range(L):
        tag = ops[idx][0]
        a_before[idx + 1] = a_before[idx] + (1 if tag != 'insert' else 0)
        b_before[idx + 1] = b_before[idx] + (1 if tag != 'delete' else 0)

    result = []
    for os_, oe_ in merged:
        alen = a_before[oe_] - a_before[os_]
        blen = b_before[oe_] - b_before[os_]
        result.append(
            "@@ -%d,%d +%d,%d @@" % (a_before[os_] + 1, alen,
                                     b_before[os_] + 1, blen)
        )
        for idx in range(os_, oe_):
            tag, i, j = ops[idx]
            if tag == 'equal':
                result.append(' ' + a[i])
            elif tag == 'delete':
                result.append('-' + a[i])
            else:
                result.append('+' + b[j])
    return result
