import heapq

def topk(stream, k):
    if k <= 0:
        return []
    heap = []  # entries: (value, -arrival_index, label)
    for i, (value, label) in enumerate(stream):
        entry = (value, -i, label)
        if len(heap) < k:
            heapq.heappush(heap, entry)
        elif entry > heap[0]:
            heapq.heapreplace(heap, entry)
    heap.sort(key=lambda e: (-e[0], -e[1]))  # value desc, arrival asc
    return [(e[0], e[2]) for e in heap]
