import re
from datetime import datetime, timedelta

_NUM = re.compile(r'\d+')


def _parse_int(token):
    token = token.strip()
    if not _NUM.fullmatch(token):
        raise ValueError(f"invalid numeric token: {token!r}")
    return int(token)


def _parse_field(field, lo_bound, hi_bound):
    field = field.strip()
    if not field:
        raise ValueError("empty cron field")
    values = set()
    for part in field.split(','):
        part = part.strip()
        if part == '':
            raise ValueError(f"empty element in list: {field!r}")
        step = 1
        base = part
        if '/' in part:
            base, _, step_str = part.partition('/')
            step_str = step_str.strip()
            if not _NUM.fullmatch(step_str):
                raise ValueError(f"invalid step: {step_str!r}")
            step = int(step_str)
            if step <= 0:
                raise ValueError("step must be a positive integer")
        if base == '*':
            lo, hi = lo_bound, hi_bound
        elif '-' in base:
            start, _, end = base.partition('-')
            lo = _parse_int(start)
            hi = _parse_int(end)
        else:
            num = _parse_int(base)
            lo = hi = num
        if not (lo_bound <= lo <= hi_bound):
            raise ValueError(f"value {lo} out of range [{lo_bound}, {hi_bound}]")
        if not (lo_bound <= hi <= hi_bound):
            raise ValueError(f"value {hi} out of range [{lo_bound}, {hi_bound}]")
        if lo > hi:
            raise ValueError(f"invalid range: {lo}-{hi}")
        value = lo
        while value <= hi:
            values.add(value)
            value += step
    return values


def next_fire(expr, after):
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"expected 5 cron fields, got {len(fields)}")

    min_f, hour_f, dom_f, month_f, dow_f = (f.strip() for f in fields)

    minutes = _parse_field(min_f, 0, 59)
    hours = _parse_field(hour_f, 0, 23)
    days_of_month = _parse_field(dom_f, 1, 31)
    months = _parse_field(month_f, 1, 12)
    days_of_week = _parse_field(dow_f, 0, 6)

    dom_restricted = dom_f != '*'
    dow_restricted = dow_f != '*'

    def day_matches(y, m, d, weekday):
        cron_dow = (weekday + 1) % 7
        if dom_restricted and dow_restricted:
            return d in days_of_month or cron_dow in days_of_week
        if dom_restricted:
            return d in days_of_month
        if dow_restricted:
            return cron_dow in days_of_week
        return True

    candidate = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    while candidate.year <= 9999:
        if candidate.month not in months:
            year, month = candidate.year, candidate.month + 1
            if month > 12:
                year, month = year + 1, 1
            candidate = datetime(year, month, 1, 0, 0)
            continue
        if not day_matches(candidate.year, candidate.month, candidate.day, candidate.weekday()):
            nxt = candidate.date() + timedelta(days=1)
            candidate = datetime(nxt.year, nxt.month, nxt.day, 0, 0)
            continue
        if candidate.hour not in hours:
            candidate = (candidate + timedelta(hours=1)).replace(minute=0, second=0, microsecond=0)
            continue
        if candidate.minute not in minutes:
            candidate = candidate + timedelta(minutes=1)
            continue
        return candidate

    raise ValueError("no matching time found within range")
