def window_medians(a, k):
    n = len(a)
    if k > n or k <= 0:
        return []

    lo = []          # max-heap stored as negated values (top is largest of lower half)
    hi = []          # min-heap (top is smallest of upper half)
    removed = {}     # value in its heap's stored form -> pending removal count

    heappush = heapq.heappush
    heappop = heapq.heappop

    lo_live = 0
    hi_live = 0

    def prune(heap):
        r = removed
        while heap and heap[0] in r:
            key = heappop(heap)
            c = r[key] - 1
            if c:
                r[key] = c
            else:
                del r[key]

    def insert(v):
        nonlocal lo_live, hi_live
        prune(lo)
        if lo and v < -lo[0]:
            heappush(lo, -v); lo_live += 1
        else:
            heappush(hi, v); hi_live += 1

    def remove(v):
        nonlocal lo_live, hi_live
        prune(lo)
        if lo and v <= -lo[0]:
            key = -v; removed[key] = removed.get(key, 0) + 1; lo_live -= 1
        else:
            removed[v] = removed.get(v, 0) + 1; hi_live -= 1

    def rebalance():
        nonlocal lo_live, hi_live
        while lo_live > hi_live + 1:
            prune(lo)
            key = heappop(lo); removed[key] = removed.get(key, 0) + 1; lo_live -= 1
            heappush(hi, -key); hi_live += 1
        while hi_live > lo_live:
            prune(hi)
            key = heappop(hi); removed[key] = removed.get(key, 0) + 1; hi_live -= 1
            heappush(lo, -key); lo_live += 1

    def median():
        prune(lo); prune(hi)
        if k & 1:
            return float(-lo[0])
        return (-lo[0] + hi[0]) * 0.5

    for i in range(k):
        insert(a[i]); rebalance()

    result = [median()]
    for i in range(k, n):
        remove(a[i - k]); rebalance(); insert(a[i]); rebalance()
