            result = {}
            memo[oid] = result
            for k, v in o.items():
                result[_copy(k)] = _copy(v)
            return result

        if isinstance(o, list):
            result = []
            memo[oid] = result
            for item in o:
                result.append(_copy(item))
            return result

        if isinstance(o, set):
            result = set()
            memo[oid] = result
            for item in o:
                result.add(_copy(item))
            return result

        if isinstance(o, tuple):
            pending = []
            memo[oid] = pending
            for item in o:
                pending.append(_copy(item))
            final = tuple(pending)
            memo[oid] = final
            return final

        if isinstance(o, frozenset):
            pending = []
            memo[oid] = pending
            for item in o:
                pending.append(_copy(item))
            final = frozenset(pending)
