import heapq


def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    INF = float('inf')
    fc = {src: 0}   # min cost from src
    fe = {src: 0}   # fewest edges among min-cost paths
    heap = [(0, 0, src)]

    while heap:
        c, e, u = heapq.heappop(heap)
        if fc.get(u, INF) != c or fe.get(u, INF) != e:
            continue
        for v, w in graph.get(u, ()):
            nc = c + w
            ne = e + 1
            cur_c = fc.get(v, INF)
            if nc < cur_c or (nc == cur_c and ne < fe.get(v, INF)):
                fc[v] = nc
                fe[v] = ne
                heapq.heappush(heap, (nc, ne, v))

    Cstar = fc.get(dst, INF)
    if Cstar == INF:
        return (None, [])

    # Build reverse adjacency of "admissible" edges:
    # edge u->v is admissible iff it keeps both min-cost and min-edge prefixes.
    radj = {}
    for u in graph:
