    can = {dst}
    stack = [dst]
    while stack:
        x = stack.pop()
        for u in radj.get(x, ()):
            if u not in can:
                can.add(u)
                stack.append(u)

    # Greedily pick the smallest next node that still completes an optimal path.
    path = [src]
