import heapq

def topo_lex(graph):
    indegree = {u: 0 for u in graph}
    for succs in graph.values():
        for v in succs:
            indegree[v] = indegree.get(v, 0) + 1

    heap = [u for u, d in indegree.items() if d == 0]
    heapq.heapify(heap)

    result = []
    push = heapq.heappush
    pop = heapq.heappop
