function toposortTasks(tasks) {
  const names = Object.keys(tasks);

  try {
    // Validate dependencies and detect cycles before running anything.
    for (const name of names) {
      const task = tasks[name];
      if (!task || typeof task.run !== 'function') {
        throw new Error(`Task "${name}" is not properly defined`);
      }
      for (const dep of task.deps || []) {
        if (!(dep in tasks)) {
          throw new Error(`Unknown dependency "${dep}" required by task "${name}"`);
        }
      }
    }

    const state = {};
    const stack = [];
    function dfs(node) {
      state[node] = 'visiting';
      stack.push(node);
      for (const dep of tasks[node].deps || []) {
        if (state[dep] === 'visiting') {
          throw new Error(`Dependency cycle detected: ${[...stack, dep].join(' -> ')}`);
        }
        if (!state[dep]) dfs(dep);
      }
      stack.pop();
      state[node] = 'visited';
    }
    for (const name of names) {
      if (!state[name]) dfs(name);
    }
  } catch (err) {
    return Promise.reject(err);
  }

