  const cache = {};
  function run(name) {
    if (cache[name]) return cache[name];
    cache[name] = Promise.resolve().then(() => compute(name));
    return cache[name];
  }

  async function compute(name) {
    const task = tasks[name];
    const deps = task.deps || [];
    const settled = await Promise.allSettled(deps.map((d) => run(d)));

    const values = {};
    let failure;
    for (let i = 0; i < deps.length; i++) {
      if (settled[i].status === 'rejected') {
        if (!failure) failure = settled[i].value;
      } else {
        values[deps[i]] = settled[i].value;
      }
    }
    if (failure) throw failure;

    return task.run(values);
  }

