type VoidKeys<E extends Record<string, unknown>> = {
  [K in keyof E]-?: [E[K]] extends [void] ? K : never;
}[keyof E];

type NonVoidKeys<E extends Record<string, unknown>> = Exclude<keyof E, VoidKeys<E>>;

export class Bus<E extends Record<string, unknown>> {
  private readonly handlers = new Map<keyof E, Array<(payload: unknown) => void>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    const handler = fn as unknown as (payload: unknown) => void;
    const list = this.handlers.get(k) ?? [];
    list.push(handler);
    this.handlers.set(k, list);

    let active = true;
    return (): void => {
      if (!active) return;
      active = false;
      const current = this.handlers.get(k);
      if (current) {
        const idx = current.indexOf(handler);
        if (idx !== -1) current.splice(idx, 1);
        if (current.length === 0) this.handlers.delete(k);
      }
    };
  }

  emit<K extends VoidKeys<E>>(k: K): void;
  emit<K extends NonVoidKeys<E>>(k: K, payload: E[K]): void;
  emit<K extends keyof E>(k: K, payload?: unknown): void {
    const list = this.handlers.get(k);
    if (list) {
      for (const handler of list.slice()) {
        handler(payload as never);
      }
    }
  }
}
