export type DeepPartial<T> = T extends Function
  ? T
  : T extends ReadonlyArray<unknown>
    ? T
    : T extends object
      ? { [K in keyof T]?: DeepPartial<T[K]> }
      : T;

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    Object.prototype.toString.call(value) === '[object Object]'
  );
}

function mergeInto(base: Record<string, unknown>, patch: Record<string, unknown>): void {
  for (const key of Object.keys(patch)) {
    const patchValue = patch[key];
    if (patchValue === undefined) continue; // explicit undefined => leave alone

    const baseValue = base[key];
    if (isPlainObject(baseValue) && isPlainObject(patchValue)) {
      const merged: Record<string, unknown> = { ...baseValue };
      mergeInto(merged, patchValue);
      base[key] = merged;
    } else {
      base[key] = patchValue; // scalars and arrays replaced wholesale
    }
  }
}

export function applyPatch<T extends object>(
  base: T,
  patch: DeepPartial<T>
): T {
  const result: Record<string, unknown> = Array.isArray(base)
    ? [...(base as unknown as ReadonlyArray<unknown>)]
    : { ...(base as unknown as Record<string, unknown>) };

  mergeInto(result, patch as unknown as Record<string, unknown>);

  return result as unknown as T;
}
